/**
 * useInsights — loads NRMS processed insight JSON files from public/data/.
 *
 * Data chain: public/data/*_insights.json → network_summary_2026.json
 * Generated by: nrms1.py pipeline (August 2026)
 * NEVER returns null/undefined — always provides fallback values so
 * KPI cards are never empty.
 */

import { useState, useEffect } from 'react';

export interface Kpi {
  label: string;
  value: string;
  color: string;
  note?: string;
}

export interface ChartSeries {
  label: string;
  value: number;
}

export interface Chart {
  type: 'pie' | 'bar' | 'scatter' | 'histogram';
  title: string;
  data: ChartSeries[];
}

export interface MlModel {
  type: string;
  n_trees?: number;
  accuracy?: number;
  r2?: number;
  growth_rate?: number;
  base_year?: number;
  target_year?: number;
  features?: string[];
}

export interface SectionInsights {
  section: string;
  last_updated: string;
  kpis: Kpi[];
  charts: Chart[];
  ml_model?: MlModel;
  insights?: string[];
  trends?: Record<string, unknown>[];
  loaded: boolean;
}

export interface NetworkSummary2026 {
  national_km: number;
  paved_km: number;
  unpaved_km: number;
  ducar_km: number;
  grand_total_km: number;
  bridges: number;
  traffic_stations: number;
  ducar_links: number;
  pim_projects: number;
  pim_budget_usd: number;
  good_pct: number;
  fair_pct: number;
  poor_pct: number;
  paved_pct: number;
  mean_aadt_2026: number;
  ml_accuracies: Record<string, number>;
  kpis: Kpi[];
  loaded: boolean;
}

