// ── Loader cache ───────────────────────────────────────────────────────────────

const _cache: Record<string, SectionInsights> = {};
const _netCache: { data: NetworkSummary2026 | null } = { data: null };

function baseUrl(): string {
  try {
    return (import.meta as { env: { BASE_URL: string } }).env.BASE_URL;
  } catch {
    return '/';
  }
}

async function loadSection(section: string, fallback: SectionInsights): Promise<SectionInsights> {
  if (_cache[section]) return _cache[section];
  try {
    const res = await fetch(`${baseUrl()}data/${section}_insights.json`);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json() as SectionInsights;
    _cache[section] = { ...data, loaded: true };
    return _cache[section];
  } catch {
    const fb = { ...fallback, loaded: true };
    _cache[section] = fb;
    return fb;
  }
}

async function loadNetworkSummary(): Promise<NetworkSummary2026> {
  if (_netCache.data) return _netCache.data;
  try {
    const res = await fetch(`${baseUrl()}data/network_summary_2026.json`);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json() as NetworkSummary2026;
    _netCache.data = { ...data, loaded: true };
    return _netCache.data;
  } catch {
    _netCache.data = { ...NET_FALLBACK, loaded: true };
    return _netCache.data;
  }
}

// ── Hooks ──────────────────────────────────────────────────────────────────────

export function useRmsInsights(): SectionInsights {
  const [ins, setIns] = useState<SectionInsights>(_cache['rms'] ?? RMS_FALLBACK);
  useEffect(() => {
    if (!_cache['rms']) loadSection('rms', RMS_FALLBACK).then(setIns);
  }, []);
  return ins;
}

